/* Actual expression operand failure cleanup and native delimiter/recovery grammar. */
#define Q3_EVAL_ENTRY EvalFixtureMain
#include "bot_eval_regression.c"
extern int PC_Evaluate(source_t *,signed long *,double *,int);
extern int PC_DollarEvaluate(source_t *,signed long *,double *,int);
static void CollectMalformed(int entry,const char *expression,int raw){source_t *source;char body[1024];if(raw)snprintf(body,sizeof(body),"%s",expression);else snprintf(body,sizeof(body),entry>=2?"(%s)":"%s\n",expression);source=EvalStart(body);Check(!entries[entry](source)&&errors>0&&!fatals&&PC_SourceHasError(source)&&!source->tokens&&!numtokens&&liveOwners==4,"malformed expression rejects without copied operand/result owners");EvalEnd(source);}
static void CollectFailure(int dollar,int index){source_t *source;const char *body=dollar?"(7 + 8)":"7 + 8\n";int target=5+index;long integer=99;double floating=99;source=EvalStart(body);failAt=target;Check(!(dollar?PC_DollarEvaluate(source,&integer,&floating,1):PC_Evaluate(source,&integer,&floating,1))&&requests==target&&fatals==1&&errors==1&&PC_SourceHasError(source)&&!integer&&!floating&&!source->tokens&&!numtokens&&liveOwners==4,"nullable first/operator/last operand copy rolls back all prior tokens");EvalEnd(source);}
static void CollectHistorical(int entry){source_t *source;token_t token;unsigned int sequence;source=EvalStart(entry>=2?"(7)":"7\n");SourceError(source,"historical recoverable diagnostic");sequence=source->errorsequence;Check(entries[entry](source)&&source->errorsequence==sequence&&errors==1&&PC_ReadToken(source,&token)&&token.type==TT_NUMBER&&token.intvalue==7&&token.floatvalue==7&&!PC_ReadToken(source,&token),"historical source errors retain native valid expression recovery");EvalEnd(source);}
static source_t *CollectMacroSource(int failure){source_t *source;token_t token;const char *text=failure?"#define MACRO(x,y) x+y\nmarker 7 + MACRO(1)\n":"#define NATIVE 7\nmarker NATIVE + 1\n";Reset(text);fatals=0;source=LoadSourceMemory((char *)text,(int)strlen(text),"native-macro-eval");Check(source&&PC_ReadToken(source,&token)&&!strcmp(token.string,"marker")&&!errors,"real native macro definition and expression cursor prepare");return source;}
static void CollectMacro(int failure){source_t *source=CollectMacroSource(failure);int baseOwners=liveOwners,baseTokens=numtokens;long integer=99;double floating=99;int result=PC_Evaluate(source,&integer,&floating,1);if(failure)Check(!result&&!integer&&!floating&&errors>0&&liveOwners==baseOwners&&numtokens==baseTokens&&!source->tokens,"failed macro expansion releases copied operand chain and preserves original definition owners");else {if(!(result&&integer==8&&floating==8&&!errors&&liveOwners==baseOwners&&numtokens==baseTokens))fprintf(stderr,"Macro state: result=%d integer=%ld float=%f errors=%d owners=%d/%d tokens=%d/%d queue=%p\n",result,integer,floating,errors,liveOwners,baseOwners,numtokens,baseTokens,(void *)source->tokens);Check(result&&integer==8&&floating==8&&!errors&&liveOwners==baseOwners&&numtokens==baseTokens,"native macro expression values and original definition owners remain");}EvalEnd(source);}
static void CollectDefined(int dollar){source_t *source=EvalStart(dollar?"(defined(unknown))":"defined unknown\n");long integer=99;double floating=99;Check((dollar?PC_DollarEvaluate(source,&integer,&floating,1):PC_Evaluate(source,&integer,&floating,1))&&!integer&&!floating&&!errors&&!source->tokens&&!numtokens&&liveOwners==4,"native parenthesized/bare defined unknown values remain");EvalEnd(source);}
#ifndef Q3_EVAL_COLLECTION_ENTRY
#define Q3_EVAL_COLLECTION_ENTRY main
#endif
int Q3_EVAL_COLLECTION_ENTRY(int argc,char **argv){if(argc>1){int proof=atoi(argv[1]);if(proof==0)CollectMalformed(0,"7 + unknown",0);else if(proof==1)CollectMalformed(2,"7 + unknown",0);else if(proof==2)CollectMalformed(0,"7 / 0",0);else if(proof==3)CollectMalformed(2,"7 / 0",0);else if(proof==4)CollectMalformed(0,"defined",0);else if(proof==5)CollectMalformed(2,"defined",0);else if(proof==6)CollectMalformed(2,"[7)",1);else if(proof==7)CollectMalformed(2,"(7",1);else if(proof==8)CollectMalformed(0,"7 \"unterminated",0);else if(proof==9)CollectMalformed(2,"(7 \"unterminated",1);else if(proof>=10&&proof<=15)CollectFailure((proof-10)/3,(proof-10)%3);else if(proof==16)CollectMacro(1);else{CollectMacro(0);CollectDefined(0);CollectDefined(1);{int entry;for(entry=0;entry<4;entry++)CollectHistorical(entry);}}return 0;} {int entry,index;for(entry=0;entry<4;entry++){CollectMalformed(entry,"7 + unknown",0);CollectMalformed(entry,"7 / 0",0);CollectMalformed(entry,"7 +",0);CollectMalformed(entry,"defined",0);CollectMalformed(entry,"defined(",0);CollectMalformed(entry,"defined(7)",0);CollectMalformed(entry,"7 \"literal\"",0);CollectHistorical(entry);if(entry>=2){CollectMalformed(entry,"[7)",1);CollectMalformed(entry,"(7",1);CollectMalformed(entry,"(7 +",1);}}for(entry=0;entry<2;entry++)for(index=0;index<3;index++)CollectFailure(entry,index);}CollectMalformed(0,"7 \"unterminated",0);CollectMalformed(2,"(7 \"unterminated",1);CollectMacro(0);CollectMacro(1);CollectDefined(0);CollectDefined(1);puts("Real expression operand cleanup, nullable copies, delimiters, defined grammar and native recovery passed (issue #48)");return 0;}
